(function(){if('loading'in HTMLImageElement.prototype)return;var o=new IntersectionObserver(function(e,t){e.forEach(function(e){if(e.isIntersecting){var t=e.target;if(t.dataset.src){t.src=t.dataset.src;t.removeAttribute('data-src')}if(t.dataset.srcset){t.srcset=t.dataset.srcset;t.removeAttribute('data-srcset')}if(t.dataset.sizes){t.sizes=t.dataset.sizes;t.removeAttribute('data-sizes')}t.removeAttribute('loading');o.unobserve(t)}})},{rootMargin:'300px'});document.querySelectorAll('img[loading="lazy"],iframe[loading="lazy"]').forEach(function(e){if(e.tagName==='IMG'){if(e.src){e.dataset.src=e.src;e.removeAttribute('src')}if(e.srcset){e.dataset.srcset=e.srcset;e.removeAttribute('srcset')}if(e.sizes){e.dataset.sizes=e.sizes;e.removeAttribute('sizes')}}o.observe(e)})})();
